# Reload both cores after a flash update (Arm DS Jython script).
#
# A system reset restarts the R5 boot ROM, which DMA-copies the M85 and R5
# images from flash into their ITCMs. The bootloader holds and resets the M85
# after the copies finish, before releasing it to start the freshly loaded
# image.
#
# Invoked from the .ds launcher generated by tools/hw_run.py.

import time
from arm_ds.debugger_v1 import Debugger

SYSCTRL = 0x44030000
CPU_MX_WAIT = SYSCTRL + 0x04
RESET_COMMAND = SYSCTRL + 0x08

RESET_SYSTEM = 0x4
RESET_M85 = 0x2

debugger = Debugger()
ec = debugger.getCurrentExecutionContext()


def wr(addr, value):
    ec.executeDSCommand("memory set AXI:0x%08X 32 0x%08X" % (addr, value))


# Restart the boot ROM / bootloader so it reloads both images from flash.
# Make sure CPUWAIT is deasserted first: a leftover hold from a previous run
# makes the bootloader's DMA copy fail.
wr(CPU_MX_WAIT, 0x0)
wr(RESET_COMMAND, RESET_SYSTEM)
time.sleep(3.0)

# Older FPGA boot ROMs release the M85 before the image copy finishes. Keep
# the second reset until the ROM includes the post-copy M85 hold/reset sequence.
wr(CPU_MX_WAIT, 0x1)
wr(RESET_COMMAND, RESET_M85)
time.sleep(0.1)
wr(CPU_MX_WAIT, 0x0)
